import java.util.*;

class Solution {
    public int hiddenMirror(String s) {
        int n = s.length();
        int[][] dp = new int[n][n];
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = 1;                                   // one letter is a mirror
            for (int j = i + 1; j < n; j++) {
                if (s.charAt(i) == s.charAt(j)) {
                    int inside = (i + 1 <= j - 1) ? dp[i + 1][j - 1] : 0;
                    dp[i][j] = inside + 2;                  // matching ends wrap the inside
                } else {
                    dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);
                }
            }
        }
        return dp[0][n - 1];
    }
}

