class Solution:
    def hiddenMirror(self, s: str) -> int:
        n = len(s)
        dp = [0] * n
        for i in range(n - 1, -1, -1):
            new = [0] * n
            new[i] = 1
            for j in range(i + 1, n):
                if s[i] == s[j]:
                    new[j] = dp[j - 1] + 2
                else:
                    new[j] = max(dp[j], new[j - 1])
            dp = new
        return dp[n - 1]

